export function mealInitial(){return {version:1,lunches:{},fridge:[]};}
export function mealDateValid(date){if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date))return false;const d=new Date(date+'T12:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===date;}
export function mealValidate(data){if(!data||data.version!==1||!data.lunches||Array.isArray(data.lunches)||typeof data.lunches!=='object'||!Array.isArray(data.fridge)||data.fridge.length>200||Object.keys(data.lunches).length>1100)throw Error('저장된 식단 형식을 확인할 수 없어요.');for(const [date,l]of Object.entries(data.lunches)){if(!mealDateValid(date)||typeof l.menu!=='string'||!l.menu.trim()||l.menu.length>500||l.confirmed!==true||!MEAL_PROTEINS.includes(l.protein))throw Error('저장된 점심 기록을 확인해 주세요.');}for(const i of data.fridge){if(typeof i.id!=='string'||typeof i.name!=='string'||!i.name.trim()||i.name.length>60||!Number.isFinite(i.qty)||i.qty<0||i.qty>100000||!['g','mL','개','팩'].includes(i.unit)||!(i.key==='custom'||MEAL_INGREDIENTS.some(x=>x[0]===i.key))||(i.expires&&!mealDateValid(i.expires)))throw Error('저장된 재료 기록을 확인해 주세요.');}if(new Set(data.fridge.map(i=>i.id)).size!==data.fridge.length)throw Error('재료 기록이 중복됐어요.');return data;}
export function mealPlanSave(data,date,menu,protein,confirmed){if(!mealDateValid(date))throw Error('유효한 날짜를 선택해 주세요.');if(typeof menu!=='string'||!menu.trim()||menu.trim().length>500)throw Error('점심 메뉴를 1~500자로 입력해 주세요.');if(!MEAL_PROTEINS.includes(protein)||confirmed!==true)throw Error('원문 메뉴와 날짜를 직접 확인해 주세요.');const next=structuredClone(data);next.lunches[date]={menu:menu.trim(),protein,confirmed:true};return mealValidate(next);}
export function mealLunchRemove(data,date){const next=structuredClone(data);delete next.lunches[date];return mealValidate(next);}
export function fridgeUpsert(data,item){const next=structuredClone(data);const idx=next.fridge.findIndex(x=>x.id===item.id);if(idx<0)next.fridge.push(item);else next.fridge[idx]=item;return mealValidate(next);}
export function fridgeRemove(data,id){const next=structuredClone(data);next.fridge=next.fridge.filter(i=>i.id!==id);return mealValidate(next);}
export function ingredientState(data,key,qty,unit,date){const rows=data.fridge.filter(i=>i.key===key);const usable=rows.filter(i=>!i.expires||i.expires>=date);const exact=usable.filter(i=>i.unit===unit);const available=exact.reduce((s,i)=>s+i.qty,0);const ambiguous=usable.some(i=>i.unit!==unit);return {available,needed:qty,unit,status:available>=qty?'enough':ambiguous?'check-unit':rows.some(i=>i.expires&&i.expires<date)&&!exact.length?'check-date':available>0?'short':'missing',missing:Math.max(0,qty-available)};}
export function mealSuggest(data,date,excluded=[]){if(!mealDateValid(date))throw Error('먼저 날짜를 선택해 주세요.');const lunch=data.lunches[date],day=Number(date.slice(-2));return ['breakfast','dinner'].map(slot=>{const candidates=MEAL_RECIPES.filter(r=>r.slot===slot&&!r.ingredients.some(i=>excluded.includes(i[0]))).map(r=>{const stock=r.ingredients.map(([key,qty,unit])=>({key,...ingredientState(data,key,qty,unit,date)}));const same=lunch&&lunch.protein!=='unknown'&&lunch.protein!=='other'&&r.protein===lunch.protein;return {...r,stock,sameLunch:!!same,score:stock.filter(x=>x.status==='enough').length*2-(same?4:0)};});candidates.sort((a,b)=>b.score-a.score||((MEAL_RECIPES.findIndex(r=>r.id===a.id)+day)%6)-((MEAL_RECIPES.findIndex(r=>r.id===b.id)+day)%6)||a.id.localeCompare(b.id));return {slot,lunchKnown:!!lunch,proteinKnown:!!lunch&&!['unknown','other'].includes(lunch.protein),recipes:candidates.slice(0,2)};});}
export function mealSearchUrl(key){const item=MEAL_INGREDIENTS.find(i=>i[0]===key);if(!item)throw Error('검색 링크는 목록의 재료만 선택할 수 있어요.');return 'https://www.coupang.com/np/search?q='+encodeURIComponent(item[1]);}
export function mealCalendar(month){if(!/^\d{4}-\d{2}$/.test(month)||!mealDateValid(month+'-01'))throw Error('월을 확인해 주세요.');const [y,m]=month.split('-').map(Number),days=new Date(Date.UTC(y,m,0)).getUTCDate();return Array.from({length:days},(_,i)=>month+'-'+String(i+1).padStart(2,'0'));}
